package com.practiq.web;
import com.practiq.common.*; import java.util.*; import org.springframework.http.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1") public class ReferenceController {final JdbcTemplate db;public ReferenceController(JdbcTemplate d){db=d;} @GetMapping("/subjects")ResponseEntity<ApiResponse<?>> subjects(){return cached(ApiResponse.ok(db.query("select subject_id,display_name from subjects order by display_name",(r,n)->Map.of("subject_id",r.getString(1),"display_name",r.getString(2)))));}@GetMapping("/question-types")ResponseEntity<ApiResponse<?>> types(@RequestParam(defaultValue="")String subject,@RequestParam(defaultValue="")String scope){return cached(ApiResponse.ok(db.query("select type_id,subject_id,display_name,scope,default_answer_mode from question_types where (?='' or subject_id=?) and (?='' or scope=?) order by subject_id,display_name",(r,n)->{var x=new LinkedHashMap<String,Object>();x.put("type_id",r.getString(1));x.put("subject_id",r.getString(2));x.put("display_name",r.getString(3));x.put("scope",r.getString(4));x.put("default_answer_mode",r.getString(5));return x;},subject.trim(),subject.trim(),scope.trim(),scope.trim())));}@GetMapping("/knowledge-points")ResponseEntity<ApiResponse<?>> knowledge(@RequestParam(defaultValue="")String subject,@RequestParam(required=false)Long parentId,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="")String cursor,@RequestParam(required=false)Integer limit){int l=limit==null?50:limit;if(l<1||l>200)throw ApiException.of(422,"VALIDATION_ERROR","Invalid request",List.of(Map.of("field","limit","message","must be between 1 and 200")));int o=PageSupport.cursor(cursor);var rows=db.query("select id,subject_id,code,display_name,parent_id,metadata_json,created_at,updated_at from knowledge_points where (?='' or subject_id=?) and ((? is null and parent_id is null) or parent_id=?) and (?='' or code ilike ? or display_name ilike ?) order by display_name,id limit ? offset ?",(r,n)->{var x=new LinkedHashMap<String,Object>();x.put("id",r.getLong(1));x.put("subject_id",r.getString(2));x.put("code",r.getString(3));x.put("display_name",r.getString(4));x.put("parent_id",r.getObject(5));x.put("metadata_json",r.getString(6));x.put("created_at",r.getObject(7));x.put("updated_at",r.getObject(8));return x;},subject.trim(),subject.trim(),parentId,parentId,q.trim(),"%"+q.trim()+"%","%"+q.trim()+"%",l+1,o);boolean more=rows.size()>l;if(more)rows=rows.subList(0,l);return cached(ApiResponse.ok(rows,Map.of("pagination",Map.of("cursor",more?PageSupport.next(o,l):"","limit",l,"hasMore",more))));}private ResponseEntity<ApiResponse<?>> cached(ApiResponse<?> body){return ResponseEntity.ok().header(HttpHeaders.CACHE_CONTROL,"public, max-age=0, s-maxage=300, stale-while-revalidate=60").body(body);}}
